head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDDST77000";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst77000.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.fnInit();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst77000.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fnDownload();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
// [저작] 기간 프리셋 버튼 — fnDisplaySearchBtnDates 재설계 (btn_cm 텍스트·gcc date 조합)

/**
 * @method
 * @name btn_pd_1w_onclick
 * @description 「1주」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_pd_1w_onclick = function () { try { const to = WebSquare.date.getCurrentServerDate('yyyyMMdd'); const from = $c.date.addDate(to, -7); const f = ($c.util.getComponent('cal_fromDate') || $c.util.getComponent('ipt_fromDate') || $c.util.getComponent('fromDate')); const t = ($c.util.getComponent('cal_toDate') || $c.util.getComponent('ipt_toDate') || $c.util.getComponent('toDate')); if (f && f.setValue) { f.setValue(from); } if (t && t.setValue) { t.setValue(to); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst77000.pd_1w' }); } };

/**
 * @method
 * @name btn_pd_1m_onclick
 * @description 「1개월」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_pd_1m_onclick = function () { try { const to = WebSquare.date.getCurrentServerDate('yyyyMMdd'); const from = $c.date.addMonth(to, -1); const f = ($c.util.getComponent('cal_fromDate') || $c.util.getComponent('ipt_fromDate') || $c.util.getComponent('fromDate')); const t = ($c.util.getComponent('cal_toDate') || $c.util.getComponent('ipt_toDate') || $c.util.getComponent('toDate')); if (f && f.setValue) { f.setValue(from); } if (t && t.setValue) { t.setValue(to); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst77000.pd_1m' }); } };

/**
 * @method
 * @name btn_pd_3m_onclick
 * @description 「3개월」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_pd_3m_onclick = function () { try { const to = WebSquare.date.getCurrentServerDate('yyyyMMdd'); const from = $c.date.addMonth(to, -3); const f = ($c.util.getComponent('cal_fromDate') || $c.util.getComponent('ipt_fromDate') || $c.util.getComponent('fromDate')); const t = ($c.util.getComponent('cal_toDate') || $c.util.getComponent('ipt_toDate') || $c.util.getComponent('toDate')); if (f && f.setValue) { f.setValue(from); } if (t && t.setValue) { t.setValue(to); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst77000.pd_3m' }); } };

/**
 * @method
 * @name btn_pd_6m_onclick
 * @description 「6개월」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_pd_6m_onclick = function () { try { const to = WebSquare.date.getCurrentServerDate('yyyyMMdd'); const from = $c.date.addMonth(to, -6); const f = ($c.util.getComponent('cal_fromDate') || $c.util.getComponent('ipt_fromDate') || $c.util.getComponent('fromDate')); const t = ($c.util.getComponent('cal_toDate') || $c.util.getComponent('ipt_toDate') || $c.util.getComponent('toDate')); if (f && f.setValue) { f.setValue(from); } if (t && t.setValue) { t.setValue(to); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst77000.pd_6m' }); } };

/**
 * @method
 * @name btn_pd_1y_onclick
 * @description 「1년」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_pd_1y_onclick = function () { try { const to = WebSquare.date.getCurrentServerDate('yyyyMMdd'); const from = $c.date.addYear(to, -1); const f = ($c.util.getComponent('cal_fromDate') || $c.util.getComponent('ipt_fromDate') || $c.util.getComponent('fromDate')); const t = ($c.util.getComponent('cal_toDate') || $c.util.getComponent('ipt_toDate') || $c.util.getComponent('toDate')); if (f && f.setValue) { f.setValue(from); } if (t && t.setValue) { t.setValue(to); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst77000.pd_1y' }); } };

/**
 * @method
 * @name btn_fnFindCorpName2_onclick
 * @description btn_fnFindCorpName2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_fnFindCorpName2_onclick = function(e){
    try {
        Promise.resolve($c.win.openPopup('/ui/jsp/JLDFIL00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } }); return false;

} catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst77000.btn_fnFindCorpName2_onclick' }); }
};

/**
 * @method
 * @name cal_fromDate_onkeyup
 * @description 「상장일 기간 선택 첫번째」 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal_fromDate_onkeyup = async function(e){
    try {
        await scwin.fnChkLmtDate();return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst77000.cal_fromDate_onkeyup' }); }
};

/**
 * @method
 * @name btn_fnSearchCorpName_onclick
 * @description btn_fnSearchCorpName 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnSearchCorpName_onclick = async function(e){
    try {
        await scwin.fnSearchCorpName(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst77000.btn_fnSearchCorpName_onclick' }); }
};

/**
 * @method
 * @name btn_fnDownload_onclick
 * @description btn_fnDownload 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnDownload_onclick = async function(e){
    try {
        await scwin.fnDownload(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst77000.btn_fnDownload_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnDownload
 * @description fn Download 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnDownload = async function () {
    const sbmOptions = {
        id: "tx_fnDownload",
        method: "post",
        action: "/listinvstg/pubprcCmpStkprcByIssue.do",
        ref: "dma_fnDownloadReq",
        target: "dlt_repMajAgntComp=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/listinvstg/pubprcCmpStkprcByIssue.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnInit
 * @description fn Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnInit = async function () {
    /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnDisplaySearchBtnDatesOnlyPeriod( "1 ') */
    await scwin.fnOrder("1", "D");
};

/**
 * @method
 * @name fnOrder
 * @description fn Order 처리
 * @param {*} mode mode
 * @param {*} stat stat
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnOrder = async function (mode, stat) {
    $c.util.getComponent("dma_fnDownloadReq").set("orderMode", mode);
    $c.util.getComponent("dma_fnDownloadReq").set("orderStat", stat);
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    const fromDate = $c.util.getComponent('cal_fromDate').getValue();
    const toDate = $c.util.getComponent('cal_toDate').getValue();
    if (!$c.date.isDate(fromDate)) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate(toDate)) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (!chkPeriod_year(fromDate, toDate, 3)) {
        return;
    }
    const chkDt = fromDate.replace(/\-/g, '');
    if (parseInt(chkDt) < 19990101) {
        await $c.win.alert("조회는 1999년 1월 1일 이후부터 가능합니다.");
        return;
    }
    if (($c.util.getComponent('cal_fromDate').getValue() == null ? '' : String($c.util.getComponent('cal_fromDate').getValue())) !== '' && ($c.util.getComponent('cal_toDate').getValue() == null ? '' : String($c.util.getComponent('cal_toDate').getValue())) !== '') {
        if (!($c.date.diffDate($c.util.getComponent('cal_fromDate').getValue(), $c.util.getComponent('cal_toDate').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
            return;
        }
    }
    $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('AKCKwd').getValue());
    if ($c.util.getComponent("ipt_currentPageSize").getValue() != null) {
        $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $c.util.getComponent("ipt_currentPageSize").getValue());
    }
    $c.util.getComponent("dma_fnDownloadReq").set("method", "pubprcCmpStkprcByIssueSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "pubprcCmpStkprcByIssue_sub");
    await scwin.tx_fnSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchCallBack
 * @description fn Search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack = function (data) {
    $("#mainContents").empty().append(data);
    $("tr:even").addClass("active");
    /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnLegendTooltip( " ') */
};

/**
 * @method
 * @name fnDownload
 * @description fn Download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDownload = async function () {
    if (!$c.date.isDate($c.util.getComponent('cal_fromDate').getValue())) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_toDate').getValue())) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (($c.util.getComponent('cal_fromDate').getValue() == null ? '' : String($c.util.getComponent('cal_fromDate').getValue())) !== '' && ($c.util.getComponent('cal_toDate').getValue() == null ? '' : String($c.util.getComponent('cal_toDate').getValue())) !== '') {
        if (!($c.date.diffDate($c.util.getComponent('cal_fromDate').getValue(), $c.util.getComponent('cal_toDate').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
            return;
        }
    }
    $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('AKCKwd').getValue());
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", "3000");
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("method", "pubprcCmpStkprcByIssueSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "pubprcCmpStkprcByIssue_down");
    await scwin.tx_fnDownload();
};

/**
 * @method
 * @name fnChkLmtDate
 * @description fn Chk Lmt Date 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnChkLmtDate = async function () {
    const dateVal = $c.util.getComponent('cal_fromDate').getValue();
    if (dateVal.length === 8) {
        if (dateVal.substring(0, 4) < 1999) {
            await $c.win.alert("조회는 1999년 1월 1일 이후부터 가능합니다.");
            $c.util.getComponent('cal_fromDate').setValue("1999-01-01");
            return false;
        }
    }
};

/**
 * @method
 * @name fnSearch1
 * @description fn Search1 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch1 = async function () {
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $c.util.getComponent("ipt_currentPageSize").getValue());
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnSearchCorpName
 * @description fn Search Corp Name 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpName = async function () {
    let val = $c.util.getComponent('AKCKwd').getValue(); if (val == null) { val = ''; }
    if (val !== "") {
        $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('AKCKwd').getValue());
        fnAKCKwdSearchCorpNameAll();
    } else {
        $c.util.getComponent("dma_fnDownloadReq").set("isurCd", "");
        await scwin.fnOrder("1", "D");
    }
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "");
};

/**
 * @method
 * @name fnSearchCorpNameAllCallBack
 * @description fn Search Corp Name All Call Back 처리
 * @param {*} items items
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpNameAllCallBack = async function (items) {
    $c.util.getComponent("dma_fnDownloadReq").set("isurCd", '');
    if (items.length === 1) {
        $c.util.getComponent("dma_fnDownloadReq").set("isurCd", items[0].isurcd);
        await scwin.fnSearchCorpCode();
    } else {
        if (items.length > 1) {
            Promise.resolve($c.win.openPopup('/ui/jsp/JLDFIL00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } });
    } else {
        await scwin.fnSearchCorpCode();
    }
}
};

/**
 * @method
 * @name fnSearchCorpCode
 * @description fn Search Corp Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpCode = async function () {
    const isurCd = ($c.util.getComponent("dma_fnDownloadReq").get("isurCd") || '');
    if (isurCd === "") {
        await $c.win.alert("조회한 회사명이 존재하지 않습니다. \n정확한 회사명을 입력해 주세요. \n회사명이 정확하지 않으시면 회사명 검색을 이용해주세요.");
        return;
    } else {
        await scwin.fnOrder("1", "D");
    }
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} isurCd isurCd
 * @param {String} kisComCd kisComCd
 * @param {String} ipt_repIsuSrtCd ipt_repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} ipt_comAbbrv ipt_comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo = function (isurCd, kisComCd, ipt_repIsuSrtCd, comNm, ipt_comAbbrv, isurSymbl, fssUnqNo) {
    let str = "";
    str += "isurCd : " + isurCd + "\n";
    str += "kisComCd : " + kisComCd + "\n";
    str += "repIsuSrtCd : " + ipt_repIsuSrtCd + "\n";
    str += "comNm : " + comNm + "\n";
    str += "comAbbrv : " + ipt_comAbbrv + "\n";
    str += "isurSymbl : " + isurSymbl + "\n";
    str += "fssUnqNo : " + fssUnqNo + "\n";
    if (ipt_repIsuSrtCd === "") {
        ipt_repIsuSrtCd = isurCd;
    }
    $c.util.getComponent('AKCKwd').setValue(ipt_comAbbrv);
    $c.util.getComponent("dma_fnDownloadReq").set("isurCd", isurCd);
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", ipt_repIsuSrtCd);
};

/**
 * @method
 * @name fnDetailView
 * @description fn Detail View 처리
 * @param {*} isurcd isurcd
 * @param {*} bzProcsNo bzProcsNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDetailView = async function (isurcd, bzProcsNo) {
    let frm = (document.popNewForm || { elements: [] });
    const html = "<form name='popNewForm' ipt_method='post'><input type='hidden' name='isurCd' value='" + isurcd + "'/><input type='hidden' name='bzProcsNo' value='" + bzProcsNo + "'></form>";
    if (frm === "undefined" || frm == null) {
        $("section").first().append(html);
        frm = (document.popNewForm || { elements: [] });
    } else {
        $c.util.getComponent('dma_fnDownloadReq').set('isurCd', isurcd);
        frm.bzProcsNo.value = bzProcsNo;
    }
    const pop_title = "popup";
    const wUrl = "/listinvstg/listcomdetail.do?method=searchListComDetailMain";
    $c.win.openPopup("", String('' || '').split(',').reduce(function (o, kv) { const p = kv.split('='); let k = (p[0] || '').replace(/\s/g, ''); const v = (p[1] || '').replace(/\s/g, ''); if (k === 'width' || k === 'height') { o[k] = v; } else if (k === 'scrollbars' || k === 'resizable' || k === 'modal') { o[k] = (v === 'yes' || v === '1'); } return o; }, (typeof pop_title !== 'undefined' ? pop_title : '') ? Object.assign({ id: "popup", scrollbars: true, resizable: false, width: "970", height: "770", type: "pageFramePopup" }, { id: (typeof pop_title !== 'undefined' ? pop_title : '') }) : { id: "popup", scrollbars: true, resizable: false, width: "970", height: "770", type: "pageFramePopup" }), {});
    frm.target = pop_title;
    frm.action = wUrl;
    await moveUrl(wUrl, {});
};
